INSERT INTO source_registry (source_id, agency, dataset_name, source_type, authority_class, jurisdiction, canonical_url, license, notes) VALUES
('SRC-CEA-V21', 'Central Electricity Authority (CEA)', 'CO2 Baseline Database for the Indian Power Sector', 'GOVERNMENT_DATABASE', 'GREEN_OFFICIAL', 'India', 'https://cea.nic.in/cdm-co2-baseline-database/?lang=en', 'Government of India Open Data', 'Official Indian national grid weighted average factor (0.716 tCO2/MWh baseline). State factors are transparent derived models.'),
